<summary>Loopback proof harness</summary>

```js
import { createServer } from "node:http";
import { pathToFileURL } from "node:url";

const input = "Please pronounce OpenClaw and ElevenLabs.";
const configuredLocators = [
  { pronunciationDictionaryId: "dict-first", versionId: "version-a" },
  { pronunciationDictionaryId: "dict-second", versionId: "version-b" },
];
const expectedWireLocators = [
  { pronunciation_dictionary_id: "dict-first", version_id: "version-a" },
  { pronunciation_dictionary_id: "dict-second", version_id: "version-b" },
];
const received = [];
const server = createServer((request, response) => {
  let raw = "";
  request.setEncoding("utf8");
  request.on("data", (chunk) => { raw += chunk; });
  request.on("end", () => {
    try {
      received.push({ path: request.url, body: JSON.parse(raw) });
      response.writeHead(200, { "content-type": "audio/mpeg" });
      response.end(Buffer.from([0x49, 0x44, 0x33]));
    } catch {
      response.writeHead(400);
      response.end();
    }
  });
});

await new Promise((resolve, reject) => {
  server.once("error", reject);
  server.listen(0, "127.0.0.1", resolve);
});

try {
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("loopback listener did not bind");
  const { buildElevenLabsSpeechProvider } = await import(
    pathToFileURL(`${process.cwd()}/extensions/elevenlabs/speech-provider-factory.ts`).href
  );
  const provider = buildElevenLabsSpeechProvider({
    formatErrorMessage: (error) => error instanceof Error ? error.message : String(error),
  });
  const baseConfig = {
    apiKey: "local-proof-placeholder",
    baseUrl: `http://127.0.0.1:${address.port}`,
    voiceId: "abcdefghij",
    modelId: "eleven_multilingual_v2",
  };
  const request = { text: input, cfg: {}, target: "audio-file", timeoutMs: 5_000 };
  const buffered = await provider.synthesize({
    ...request,
    providerConfig: { ...baseConfig, pronunciationDictionaryLocators: configuredLocators },
  });
  const streamed = await provider.streamSynthesize({
    ...request,
    providerConfig: { ...baseConfig, pronunciationDictionaryLocators: configuredLocators },
  });
  const reader = streamed.audioStream.getReader();
  let streamBytes = 0;
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    streamBytes += value.byteLength;
  }
  await streamed.release();
  await provider.synthesize({
    ...request,
    providerConfig: { ...baseConfig, pronunciationDictionaryLocators: [] },
  });
  let oversizedRejected = false;
  let oversizedError = null;
  const requestsBeforeOversized = received.length;
  try {
    await provider.synthesize({
      ...request,
      providerConfig: {
        ...baseConfig,
        pronunciationDictionaryLocators: Array.from({ length: 4 }, (_, index) => ({
          pronunciationDictionaryId: `dict-${index}`,
          versionId: `version-${index}`,
        })),
      },
    });
  } catch (error) {
    oversizedError = error instanceof Error ? error.message : String(error);
    oversizedRejected = oversizedError.includes("supports at most three entries");
  }

  const summarize = ({ path, body }) => ({
    path,
    text: body.text,
    locators: body.pronunciation_dictionary_locators ?? null,
  });
  const output = {
    bufferedAudioBytes: buffered.audioBuffer.byteLength,
    streamedAudioBytes: streamBytes,
    requests: received.map(summarize),
    locatorsMatch: received.length === 3 && received.slice(0, 2).every(({ body }) =>
      JSON.stringify(body.pronunciation_dictionary_locators) === JSON.stringify(expectedWireLocators),
    ),
    inputPreserved: received.length === 3 && received.every(({ body }) => body.text === input),
    emptyListOmitted: received.length === 3 && received[2].body.pronunciation_dictionary_locators === undefined,
    oversizedRejected,
    requestsBeforeOversized,
    requestsAfterOversized: received.length,
    oversizedError,
  };
  console.log(JSON.stringify(output));
  if (
    received.length !== 3 ||
    buffered.audioBuffer.byteLength === 0 ||
    streamBytes === 0 ||
    !output.locatorsMatch ||
    !output.inputPreserved ||
    !output.emptyListOmitted ||
    !output.oversizedRejected ||
    output.requestsBeforeOversized !== output.requestsAfterOversized
  ) {
    process.exitCode = 1;
  }
} finally {
  await new Promise((resolve) => server.close(resolve));
}
```

