const paragraph = 'CRLF proof paragraph.';
const source = `${paragraph}\r\n\r\n${paragraph}\r\n\r\n${fence}\r\n\r\nDone.`;
const expected = `${paragraph}\r\n\r\n${fence}\r\n\r\nDone.`;
