      const body = await json(req);
      assert.equal(body.model,'crlf-fixture');
      assert.equal(body.stream,true);
      assert(Array.isArray(body.input));
      requests++;
      const message = {id:'msg_crlf_fixture',type:'message',role:'assistant',status:'completed',
