      const send=(event:unknown)=>res.write(`data: ${JSON.stringify(event)}\n\n`);
      send({type:'response.output_item.added',output_index:0,item:{...message,status:'in_progress',content:[]}});
      // Single-character SSE deltas deliberately put every CR/LF on separate events.
      for(const char of source) {
        signal.throwIfAborted();
        send({type:'response.output_text.delta',item_id:message.id,output_index:0,content_index:0,delta:char});
        await delay(12,undefined,{signal});
