      await delay(200,undefined,{signal});
      send({type:'response.output_text.done',item_id:message.id,output_index:0,content_index:0,text:source});
      send({type:'response.output_item.done',output_index:0,item:message});
      send({type:'response.completed',response:{id:'resp_crlf_fixture',status:'completed',output:[message],
