let client: Awaited<ReturnType<typeof connectProofClient>> | undefined;
const events: Array<{event:string;payload:any}> = [];
let failed: unknown;
const parentEnvironment = captureEnv(['OPENCLAW_HOME','OPENCLAW_STATE_DIR','OPENCLAW_CONFIG_PATH']);
const textOf=(message:any):string=>typeof message?.content === 'string' ? message.content :
  Array.isArray(message?.content) ? message.content.filter((part:any)=>typeof part?.text === 'string').map((part:any)=>part.text).join('') : '';
try {
  const cfg:any = createOpenAiResponsesModelConfig({baseUrl:`http://127.0.0.1:${provider.claim.port}`,
    providerId:'crlf-proof',modelId:'crlf-fixture',reasoning:false,toolProfile:'minimal'});
