    signal,onEvent:event=>{ if(event.event && ['chat','agent','session.message'].includes(event.event))
      events.push({event:event.event,payload:event.payload}); }});
  await client.request('sessions.subscribe',{});
  await client.request('sessions.create',{key:sessionKey,agentId:'main'});
  await client.request('sessions.messages.subscribe',{key:sessionKey,subscriptionId:`crlf-proof-${variant}`});
  const sent = await client.request<any>('chat.send',{sessionKey,message:'Return the fixed CRLF fixture.',
    deliver:false,idempotencyKey:randomUUID()},{timeoutMs:30_000});
