// Local proof for #182178 (not committed): real Gateway + anthropic-messages transport against a loopback mock.
import { appendFileSync } from "node:fs";
import { createServer } from "node:http";
import { afterEach, expect, it } from "vitest";
import type { ModelDefinitionConfig, ModelProviderConfig } from "../src/config/types.models.js";
import { startGatewayWithClient } from "../src/gateway/test-helpers.e2e.js";
import { listenProofProvider, useRuntimeProofFixture } from "./runtime-proof.test-support.js";

const createFixture = useRuntimeProofFixture(afterEach);

const PROVIDER_ID = "mock-anthropic";
const PRIMARY_MODEL_ID = "claude-opus-5-5";
const FALLBACK_MODEL_ID = "claude-sonnet-5-5";
const TOKEN = "issue182178-proof-token";
const RECOVERED_MARKER = "ISSUE182178_VISIBLE_ANSWER";
const THINKING_TEXT = "ISSUE182178_PRIVATE_REASONING";
const THINKING_SIGNATURE = "issue182178-signature";
const RETRY_PHRASE = "recorded reasoning but did not produce a user-visible answer";

type Turn = "thinking-length" | "thinking-stop" | "refusal" | "text";

function anthropicTurn(kind: Turn, model: string, id: string): string {
  const thinking = kind === "thinking-length" || kind === "thinking-stop";
  const events: unknown[] = [
    {
      type: "message_start",
      message: {
        id,
        type: "message",
        role: "assistant",
        model,
        content: [],
        stop_reason: null,
        usage: { input_tokens: 640, output_tokens: 0 },
      },
    },
    ...(thinking
      ? [
          {
            type: "content_block_start",
            index: 0,
            content_block: { type: "thinking", thinking: "", signature: "" },
          },
          {
            type: "content_block_delta",
            index: 0,
            delta: { type: "thinking_delta", thinking: THINKING_TEXT },
          },
          {
            type: "content_block_delta",
            index: 0,
            delta: { type: "signature_delta", signature: THINKING_SIGNATURE },
          },
          { type: "content_block_stop", index: 0 },
        ]
      : kind === "text"
        ? [
            { type: "content_block_start", index: 0, content_block: { type: "text", text: "" } },
            {
              type: "content_block_delta",
              index: 0,
              delta: { type: "text_delta", text: RECOVERED_MARKER },
            },
            { type: "content_block_stop", index: 0 },
          ]
        : []),
    {
      type: "message_delta",
      delta:
        kind === "refusal"
          ? {
              stop_reason: "refusal",
              stop_sequence: null,
              stop_details: {
                type: "refusal",
                category: "reasoning_extraction",
                explanation: "Synthetic refusal for the local proof.",
              },
            }
          : {
              stop_reason: kind === "thinking-length" ? "max_tokens" : "end_turn",
              stop_sequence: null,
            },
      usage: { output_tokens: kind === "thinking-length" ? 4096 : 64 },
    },
    { type: "message_stop" },
  ];
  return events.map((event) => `event: ${(event as { type: string }).type}\ndata: ${JSON.stringify(event)}\n\n`).join("");
}

function model(id: string): ModelDefinitionConfig {
  return {
    id,
    name: id,
    api: "anthropic-messages",
    reasoning: true,
    input: ["text"],
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: 200_000,
    maxTokens: 4096,
  };
}

function buildProvider(baseUrl: string) {
  const config: ModelProviderConfig = {
    baseUrl,
    apiKey: "sk-ant-api03-issue182178-proof", // pragma: allowlist secret
    api: "anthropic-messages",
    models: [model(PRIMARY_MODEL_ID), model(FALLBACK_MODEL_ID)],
  };
  return { providerId: PROVIDER_ID, modelRef: `${PROVIDER_ID}/${PRIMARY_MODEL_ID}`, config } as const;
}

type CapturedRequest = {
  model: string;
  sendsRetryInstruction: boolean;
  carriesPartialThinking: boolean;
};

function capture(body: string): CapturedRequest {
  const parsed = JSON.parse(body) as { model: string; messages: unknown[] };
  const messages = JSON.stringify(parsed.messages);
  return {
    model: parsed.model,
    sendsRetryInstruction: body.includes(RETRY_PHRASE),
    carriesPartialThinking: messages.includes(THINKING_SIGNATURE),
  };
}

async function runScenario(name: string, script: Turn[], withFallback = false) {
  const fixture = await createFixture(`openclaw-issue182178-${name}-`, TOKEN);
  let providerServer: ReturnType<typeof createServer> | undefined;
  let gateway: Awaited<ReturnType<typeof startGatewayWithClient>> | undefined;
  const requests: CapturedRequest[] = [];
  try {
    providerServer = createServer((request, response) => {
      let body = "";
      request.setEncoding("utf8");
      request.on("data", (chunk) => {
        body += chunk;
      });
      request.on("end", () => {
        const captured = capture(body);
        requests.push(captured);
        const kind = script[requests.length - 1] ?? "text";
        response.writeHead(200, {
          "content-type": "text/event-stream; charset=utf-8",
          "cache-control": "no-cache",
        });
        response.end(anthropicTurn(kind, captured.model, `msg_issue182178_${requests.length}`));
      });
    });
    const providerUrl = await listenProofProvider(providerServer);
    const provider = buildProvider(providerUrl);
    const cfg = fixture.config(provider, {
      model: {
        primary: provider.modelRef,
        fallbacks: withFallback ? [`${PROVIDER_ID}/${FALLBACK_MODEL_ID}`] : [],
      },
    });
    const sessionKey = `agent:main:issue182178-${name}`;
    gateway = await startGatewayWithClient({
      cfg,
      configPath: fixture.configPath,
      token: TOKEN,
      clientDisplayName: `issue182178-${name}`,
    });
    const started = await gateway.client.request<{ runId?: string; status?: string }>(
      "chat.send",
      { sessionKey, message: "answer my question", deliver: false, idempotencyKey: `issue182178-${name}` },
    );
    expect(started.status).toBe("started");
    const waited = await gateway.client.request<{ status?: string }>(
      "agent.wait",
      { runId: started.runId, timeoutMs: 60_000 },
      { timeoutMs: 65_000 },
    );
    const history = await gateway.client.request<{ messages?: unknown[] }>("chat.history", {
      sessionKey,
      limit: 20,
    });
    const visible = (history.messages ?? [])
      .filter((message) => (message as { role?: string }).role !== "user")
      .map((message) => {
        const content = (message as { content?: unknown }).content;
        const text = Array.isArray(content)
          ? content
              .map((block) => (block as { text?: string }).text ?? `[${(block as { type?: string }).type}]`)
              .join(" ")
          : String(content ?? "");
        return `${(message as { role?: string }).role}: ${text}`.slice(0, 160);
      });
    const report = { scenario: name, waitStatus: waited.status, requests, visible };
    appendFileSync(process.env.ISSUE182178_PROOF_OUT ?? "/dev/null", `${JSON.stringify(report, null, 2)}\n`);
    return report;
  } finally {
    await fixture.close(gateway, providerServer);
  }
}

it("reasoning-only max_tokens turn on anthropic-messages", { timeout: 120_000 }, async () => {
