row12_artifacts="$(mktemp -d)"
OPENCLAW_ROW12_ARTIFACT_DIR="$row12_artifacts" OPENCLAW_ROW12_STAGE=seed node --import ./scripts/tsx.mjs proof-row12-watched-context.mts
