```typescript
// Isolated stock source-Gateway + deterministic loopback HTTP provider.
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import { createServer } from "node:http";
import type { OpenClawConfig } from "./src/config/types.openclaw.js";
import { nativeModel } from "./test/e2e/qa-lab/runtime/native-provider-proof-fixture.js";
const artifacts = process.env.OPENCLAW_ROW12_ARTIFACT_DIR;
assert(artifacts, "artifact directory required");
const stage = process.env.OPENCLAW_ROW12_STAGE ?? "seed";
const home = path.join(artifacts, "home");
const stateDir = path.join(home, ".openclaw");
const workspace = path.join(home, "workspace");
await fs.mkdir(workspace, { recursive: true });
await fs.mkdir(stateDir, { recursive: true });
Object.assign(process.env, {
  OPENCLAW_HOME: home,
  OPENCLAW_STATE_DIR: stateDir,
  OPENCLAW_CONFIG_PATH: path.join(stateDir, "openclaw.json"),
  OPENCLAW_SKIP_CHANNELS: "1", OPENCLAW_SKIP_CRON: "1",
  OPENCLAW_DISABLE_CONFIG_WATCH: "1", OPENCLAW_DISABLE_LOG_FILE: "1",
});
type Body = { model: string; messages: Array<{role: string; content: unknown}>; tools?: unknown[] };
const requests: Array<{url: string; body: Body; rawBody: string}> = [];
const responses: string[] = [];
const completions: unknown[] = [];
const save = (name: string, data: unknown) => fs.writeFile(path.join(artifacts, `${stage}-${name}.json`), JSON.stringify(data, null, 2) + "\n");
const provider = createServer((req, res) => {
  void (async () => {
    const chunks: Buffer[] = [];
    for await (const chunk of req) chunks.push(Buffer.from(chunk));
    const rawBody = Buffer.concat(chunks).toString();
    const body = JSON.parse(rawBody) as Body;
    requests.push({ url: req.url ?? "", body, rawBody });
    const text = `ROW12_${stage.toUpperCase()}_${requests.length}_DONE`;
    const wire = [
      { id: "row12-response", object: "chat.completion.chunk", created: 1, model: body.model,
        choices: [{ index: 0, delta: { role: "assistant", content: text }, finish_reason: null }] },
      { id: "row12-response", object: "chat.completion.chunk", created: 1, model: body.model,
        choices: [{ index: 0, delta: {}, finish_reason: "stop" }] },
    ].map((chunk) => `data: ${JSON.stringify(chunk)}\n\n`).join("") + "data: [DONE]\n\n";
    responses.push(wire);
    await save("provider-requests", requests);
    await save("response-wire", responses);
    res.writeHead(200, { "content-type": "text/event-stream" });
    res.end(wire);
  })().catch((error) => res.writeHead(500).end(String(error)));
});
await new Promise<void>((resolve) => provider.listen(0, "127.0.0.1", resolve));
const address = provider.address();
assert(address && typeof address !== "string");
const config: OpenClawConfig = {
  gateway: { mode: "local", reload: { mode: "off" } },
  cron: { enabled: false }, memory: { search: { enabled: false } },
  update: { checkOnStart: false, auto: { enabled: false } },
  plugins: { allow: ["openai"], slots: { memory: "none" } },
  agents: {
    defaults: { model: "row12-proof/row12-model", modelPolicy: { allow: ["row12-proof/row12-model"] },
      models: { "row12-proof/row12-model": {} }, workspace, skipBootstrap: true },
    entries: { main: { model: "row12-proof/row12-model", workspace } },
  },
  models: { mode: "replace", providers: { "row12-proof": {
    api: "openai-completions", baseUrl: `http://127.0.0.1:${address.port}/v1`,
    apiKey: "synthetic-row12-key", models: [nativeModel("row12-model", { contextWindow: 131072 })],
  } } },
  tools: { profile: "full", codeMode: false, toolSearch: false },
};
const { OpenClawSchema } = await import("./src/config/zod-schema.js");
OpenClawSchema.parse(config);
await fs.writeFile(process.env.OPENCLAW_CONFIG_PATH!, JSON.stringify(config));
const { startGatewayServer } = await import("./src/gateway/server.js");
const { acquireGatewayE2ePortBlock, startClaimedGateway } = await import("./src/gateway/test-helpers.listener.js");
const { connectGatewayClient, disconnectGatewayClient } = await import("./src/gateway/test-helpers.e2e.js");
const { registerMainSessionGroupWatch, handleSessionStateSessionReset } = await import("./src/sessions/session-state-events.js");
const { upsertSessionEntryCore } = await import("./src/config/sessions/session-accessor.js");
const { closePreparedModelRuntimeSnapshots } = await import("./src/agents/prepared-model-runtime.lifecycle.js");
const { clearRuntimeConfigSnapshot, getRuntimeConfigSnapshot } = await import("./src/config/runtime-snapshot.js");
const { runEmbeddedAgent } = await import("./src/agents/embedded-agent-runner/run-orchestrator.js");
const { prepareSystemAgentRunAdmission } = await import("./src/agents/admitted-run-context.js");
const { runSystemAgentGatewayTask } = await import("./src/gateway/server-methods/system-agent-execution.js");
const { createUserTurnTranscriptRecorder } = await import("./src/sessions/user-turn-transcript.js");
const sessionKey = "agent:main:main";
const sessionId = "synthetic-row12-main";
const target = { agentId: "main", sessionKey, sessionId,
  storePath: path.join(stateDir, "agents", "main", "agent", "openclaw-agent.sqlite") };
const groupKey = "agent:main:telegram:group:synthetic-row12";
let gateway: Awaited<ReturnType<typeof startGatewayServer>> | undefined;
let client: Awaited<ReturnType<typeof connectGatewayClient>> | undefined;
const buildStamp: { head: string; inputsClean: boolean } = JSON.parse(await fs.readFile("dist/.buildstamp", "utf8"));
const summary: Record<string, unknown> = {
  stage, pid: process.pid, head: execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim(),
  runtime: process.version, configValidated: true,
  buildStamp,
  driverSha256: createHash("sha256").update(await fs.readFile("proof-row12-watched-context.mts")).digest("hex"),
  allTrackedInputsClean: execFileSync("git", ["diff", "HEAD", "--name-only"], { encoding: "utf8" }).trim() === "",
  trackedProductionClean: execFileSync("git", ["diff", "--name-only", "--", "src", ":(exclude)*test*"], { encoding: "utf8" }).trim() === "",
  ownerHashes: Object.fromEntries(await Promise.all([
    "src/agents/embedded-agent-runner/run/attempt-system-prompt-prepare.ts",
    "src/agents/embedded-agent-runner/run/attempt-prompt-phase.ts",
    "src/agents/watched-sessions-prompt.ts",
  ].map(async (file) => [file, createHash("sha256").update(await fs.readFile(file)).digest("hex")]))),
};
try {
  const claim = await acquireGatewayE2ePortBlock();
  gateway = await startClaimedGateway(claim, () => startGatewayServer(claim.port, {
    bind: "loopback", controlUiEnabled: false,
    auth: { mode: "token", token: "synthetic-row12-gateway-token" },
  }));
  await gateway.startupSettled;
  client = await connectGatewayClient({ url: `ws://127.0.0.1:${claim.port}`,
    token: "synthetic-row12-gateway-token", scopes: ["operator.admin"], requestTimeoutMs: 150000 });
  summary.health = await client.request("health", {});
  summary.scope = "real source-Gateway admitted system-agent task and durable embedded turn, not chat.send queue completion";
  const runConfig = getRuntimeConfigSnapshot();
  assert(runConfig, "Gateway owns admitted runtime config");
  await upsertSessionEntryCore(target, { sessionId, updatedAt: Date.now() });
  const turn = async (message: string) => {
    const runId = randomUUID();
    const admission = prepareSystemAgentRunAdmission(runConfig, runId, "main", "system-agent.turn");
    const recorder = createUserTurnTranscriptRecorder({
      target: { ...target, cwd: workspace, config: runConfig },
      input: { text: message, timestamp: Date.now(), idempotencyKey: `${runId}:user` },
    });
    try {
      const result = await runSystemAgentGatewayTask(() => runEmbeddedAgent({
        preparedRunAdmission: admission, userTurnTranscriptRecorder: recorder,
        sessionId, sessionKey, sessionTarget: target, agentId: "main",
        agentDir: path.join(stateDir, "agents", "main", "agent"), workspaceDir: workspace,
        config: runConfig, prompt: message, transcriptPrompt: message,
        provider: "row12-proof", model: "row12-model", timeoutMs: 120000, runId,
      }));
      completions.push({ message, runId, result });
      await save("completions", completions);
      assert(!result.meta.error, "actual embedded turn completes without model error");
      assert(JSON.stringify(result).includes(`ROW12_${stage.toUpperCase()}_${requests.length}_DONE`), "returned result contains captured response");
    } finally { admission.close(); }
  };
  if (stage === "seed") {
    await turn("ROW12_INITIAL: acknowledge this request.");
    assert.equal(await registerMainSessionGroupWatch({ sessionKey: groupKey, agentId: "main" }), true);
    await upsertSessionEntryCore({ sessionKey: groupKey }, { sessionId: "synthetic-watched-row12", displayName: "Original synthetic room", updatedAt: 1 });
    await turn("ROW12_WATCH_ADDED: acknowledge this request.");
  } else {
    await upsertSessionEntryCore({ sessionKey: groupKey }, { sessionId: "synthetic-watched-row12", displayName: "Renamed synthetic room", updatedAt: 2 });
    await turn("ROW12_AFTER_COLD_REOPEN: acknowledge this request.");
    await handleSessionStateSessionReset(sessionKey);
    await turn("ROW12_WATCH_REMOVED: acknowledge this request.");
  }
  assert.equal(requests.length, 2, "two provider HTTP calls per process stage");
  const system = (body: Body) => body.messages.filter((m) => m.role === "system" || m.role === "developer");
  summary.sameSystemBytes = JSON.stringify(system(requests[0]!.body)) === JSON.stringify(system(requests[1]!.body));
  summary.watchAbsentFromSystem = requests.every((request) => !JSON.stringify(system(request.body)).includes(groupKey));
  summary.sameTools = JSON.stringify(requests[0]!.body.tools) === JSON.stringify(requests[1]!.body.tools);
  summary.priorRequestPrefixIdentical = JSON.stringify(requests[1]!.body.messages.slice(0, requests[0]!.body.messages.length)) === JSON.stringify(requests[0]!.body.messages);
  if (stage === "seed") {
    summary.currentWatchInNewTurn = JSON.stringify(requests[1]!.body.messages.slice(requests[0]!.body.messages.length)).includes("Original synthetic room");
  }
  if (stage === "reopen") {
    const newTail = JSON.stringify(requests[1]!.body.messages.slice(requests[0]!.body.messages.length));
    summary.removalHasNewEmptySnapshot = newTail.includes("Watched Sessions") && newTail.includes("none") && !newTail.includes("Renamed synthetic room");
    const prior = JSON.parse(await fs.readFile(path.join(artifacts, "seed-provider-requests.json"), "utf8")) as typeof requests;
    summary.coldReopenRetainsOriginalRequest = JSON.stringify(requests[0]!.body.messages.slice(0, prior[1]!.body.messages.length)) === JSON.stringify(prior[1]!.body.messages);
    summary.oldWatchCarrierRetained = JSON.stringify(requests[0]!.body.messages).includes("Original synthetic room");
    summary.renamedWatchInNewCarrier = JSON.stringify(requests[0]!.body.messages).includes("Renamed synthetic room");
  }
} catch (error) {
  summary.error = error instanceof Error ? error.message : String(error);
  await save("setup-error", summary);
} finally {
  summary.providerRequests = requests.length;
  if (client) await disconnectGatewayClient(client);
  if (gateway) await gateway.close({ reason: "row12 isolated proof complete" });
  await closePreparedModelRuntimeSnapshots();
  clearRuntimeConfigSnapshot();
  provider.closeAllConnections();
  await new Promise<void>((resolve) => provider.close(() => resolve()));
  await save("summary", summary);
}
console.log(JSON.stringify(summary));
assert.equal(summary.error, undefined, "fixture and real turns must complete before prefix verdict");
assert.equal(summary.allTrackedInputsClean, true);
assert.equal(buildStamp.head, summary.head, "built plugin/runtime artifacts match source commit");
assert.equal(buildStamp.inputsClean, true);
assert.equal(summary.sameSystemBytes, true, "watch changes must not rewrite system before history");
assert.equal(summary.watchAbsentFromSystem, true, "live watch inventory belongs to its turn");
assert.equal(summary.sameTools, true);
assert.equal(summary.priorRequestPrefixIdentical, true, "prior request prefix stays byte-identical");
if (stage === "seed") assert.equal(summary.currentWatchInNewTurn, true, "watch awareness remains in the governed turn");
if (stage === "reopen") {
  assert.equal(summary.removalHasNewEmptySnapshot, true, "removal supersedes earlier watches beside the new turn");
  assert.equal(summary.coldReopenRetainsOriginalRequest, true, "cold process replay preserves historical carrier");
  assert.equal(summary.oldWatchCarrierRetained, true);
  assert.equal(summary.renamedWatchInNewCarrier, true);
}
